files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.theme-toggler {
  position: absolute;
  top: 20px;
  right: 20px;
}

.theme-toggler__checkbox + span {
  display: block;
  width: 40px;
  height: 40px;
  border: 2px solid transparent;
  border-radius: 4px;
  background-color: #1e1e1e;
  background-image: url(../svg/moon.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: 80%;
  cursor: pointer;
}

.theme-toggler__checkbox:hover + span {
  opacity: 0.9;
}

.theme-toggler__checkbox:focus + span {
  outline: 2px solid #ffc802;
}

.theme-toggler__checkbox:checked + span {
  border: 2px solid #ffc802;
  background-color: #fff;
  background-image: url(../svg/sun.svg);
}

.theme-toggler__checkbox:checked:focus + span {
  outline: 2px solid #1e1e1e;
}
